    ('1ee1e668-a44a-47f0-840a-c1d5e804ff2c'::uuid, 'mystery', '8', '7', 'card-stats-2026-11-12-rollback:1ee1e668-a44a-47f0-840a-c1d5e804ff2c:mystery', 'rollback of card-stats-2026-11-12: mystery ''7'' restored on Puka Pukara Archaeological Complex', 'de5774b8eef8f23c98c9b1212af0523d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 8 from (''Fortress/citadel'', ''1000 - 1500 AD'') is shared by 5 curated site(s)"}, {"source": "production export 3433e767f34031a8 (2026-11-12 10:36:17.26111+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 103 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07d''s own export (2026-11-07 15:22:34.233295+00))"}, {"source": "remediation_change_log:82222", "url": "remediation_change_log", "quote": "phase4:p4-2056:chunk-0001: description ''Puka Pukara is an ancient Inca fortress and military complex situated in the Cusco Region of Peru, near the city of Cusco. The site features large stone walls, terraces, and staircases. It served as a strategic defensive fortification protecting the capital city of Cusco and the broader Inca Empire.[1]'' -> ''Puka Pukara (Quechua puka red, pukara fortress, \"red fortress\", hispanicized spellings Pucapucara, Puca Pucara, Puca Pucará) is a site of military ruins in Peru situated in the Cusco Region, Cusco Province, Cusco District [1]. Puka Pukara is located in mid-southern Peru, about 7 kilometres from Cusco, on the road to Pisac, near to the Antisuyo, the jungle portion of the former Incan empire [1]. The fort is located on high ground overlooking the Cusco valley and Tambo Machay [1]. Although less is known about Puka Pukara than many other Incan ruins, there is a theory that this site was probably constructed during the reign of Pachacutec [1].''"}, {"source": "remediation_change_log:144542", "url": "remediation_change_log", "quote": "served-image-2026-09-30-005: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/7/78/Tambo_Machay_D%C3%A9cembre_2006.jpg'' -> ''/data/images/wiki/1ee1e668/Puka_Pukara_Inca_site,_Peru.webp''"}, {"source": "remediation_change_log:333695", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-009-001: thumbnail_url ''/data/images/wiki/1ee1e668/Puka_Pukara_Inca_site,_Peru.webp'' -> ''/data/images/wiki/1ee1e668/Tambo_Machay_Décembre_2006.webp''"}]'::jsonb),
