    ('234bd55f-9444-44e9-8fde-7e66c049561d'::uuid, 'mystery', '9', '8', 'card-stats-2026-11-12-rollback:234bd55f-9444-44e9-8fde-7e66c049561d:mystery', 'rollback of card-stats-2026-11-12: mystery ''8'' restored on Puruchuco', 'cf9f8f9560b3d857c7ddd0aa64e6857d', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 9 from (''Castle/palace'', ''500 - 1000 AD'') is shared by 2 curated site(s)"}, {"source": "production export 3433e767f34031a8 (2026-11-12 10:36:17.26111+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 103 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07d''s own export (2026-11-07 15:22:34.233295+00))"}, {"source": "remediation_change_log:33425", "url": "remediation_change_log", "quote": "phase4:p4-0018:chunk-0001: description \"Puruchuco, meaning ''feather hat'' in Quechua, is an Inca-period administrative center in Lima''s Ate district, Peru, dating to 1440-1532 AD. The complex served as the palace of a Curaca (local ruler) and a center for goods redistribution and religious rituals. Over 2,000 mummified remains and nearly 60,000 artifacts were excavated from its vast cemetery, with burials from ten social classes. In 2004, archaeologists discovered the first documented gunshot victim in the Americas, an Inca skull bearing musket wounds from the Spanish conquest.\" -> ''Puruchuco is an archaeological site in Peru that was an administrative center of the Inca period (1438–1533), located in the Ate District, in Lima [1]. The construction of this architectural complex comes from the Inca culture [1]. Puruchuco is located in the sector Huaquerones, a land of pyramids with ramps that contains one of the largest cemeteries in the Inca culture [1].''"}, {"source": "remediation_change_log:95240", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''1000 -