    ('24f1c052-5bc8-490e-9b1e-ccce0c05611b'::uuid, 'antiquity', '8', '2', 'card-stats-2026-11-12-rollback:24f1c052-5bc8-490e-9b1e-ccce0c05611b:antiquity', 'rollback of card-stats-2026-11-12: antiquity ''2'' restored on Yeavering', 'ccb48708d22ee393fdbd11a7071bbe94', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -3500"}, {"source": "production export 3433e767f34031a8 (2026-11-12 10:36:17.26111+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 103 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07d''s own export (2026-11-07 15:22:34.233295+00))"}, {"source": "remediation_change_log:80730", "url": "remediation_change_log", "quote": "phase4:p4-2006:chunk-0001: description ''Yeavering is a hamlet in the civil parish of Kirknewton, Northumberland, situated on the River Glen at the northern edge of the Cheviot Hills [1]. The site is renowned for a large Anglo-Saxon period settlement that archaeologists have identified as one of the royal seats of the kings of Bernicia during the 7th century AD [1].'' -> \"Evidence for human activity in the vicinity has been found from the Mesolithic, Neolithic and Bronze Age periods, although the first significant settlement at Yeavering occurred in the Iron Age [1]. In this period, a heavily inhabited hillfort was constructed on Yeavering Bell which appears to have been a major settlement centre at the time [1]. According to Book 2 Chapter 14 of the Ecclesiastical History of the Venerable Bede, in the year 627 Bishop Paulinus of York accompanied the Northumbrian king Edwin and his queen Æthelburg to their royal vill, Adgefrin [1]. The name of Yeavering is first attested in Bede''s Ecclesiastical History of the English People of 731, where it has the form ad gefrin [1]. To the north of the Bell, the land drops off to a terrace 72 metres above sea level, which is where the Anglo-Saxon settlement was located [1]. In the early medieval period, the area was home to Gefrin (Yeavering), a Royal settlement in the Anglo-Saxon ruled kingdom of Bernicia [1].\""}, {"source": "remediation_change_log:95285", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:95286", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s004: period_start ''1'' -> None"}, {"source": "remediation_change_log:144697", "url": "remediation_change_log", "quote": "served-image-2026-09-30-005: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Yeavering_-_geograph.org.uk_-_1381782.jpg/400px-Yeavering_-_geograph.org.uk_-_1381782.jpg'' -> ''/data/images/wiki/24f1c052/Old Yeavering 20140525.webp''"}, {"source": "remediation_change_log:235625", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:235626", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s002: period_start None -> ''501''"}, {"source": "remediation_change_log:418481", "url": "remediation_change_log", "quote": "2026-11-12_mechanical-period-fix-s001: period_name ''500 - 1000 AD'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:418482", "url": "remediation_change_log", "quote": "2026-11-12_mechanical-period-fix-s001: period_start ''501'' -> ''-3500''"}]'::jsonb),
