    ('b0fdd6ca-3571-4452-9e64-9689ceb1445b'::uuid, 'mystery', '10', '9', 'card-stats-2026-11-12-rollback:b0fdd6ca-3571-4452-9e64-9689ceb1445b:mystery', 'rollback of card-stats-2026-11-12: mystery ''9'' restored on Pisissarfik', 'c43af6e523930b1513ff8a0a0ede744e', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 10 from (''Natural feature'', ''1500+ AD'') is shared by 1 curated site(s)"}, {"source": "production export 3433e767f34031a8 (2026-11-12 10:36:17.26111+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 103 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07d''s own export (2026-11-07 15:22:34.233295+00))"}, {"source": "remediation_change_log:28314", "url": "remediation_change_log", "quote": "phase3:batch-0109:chunk-0001: site_type ''City/town/settlement'' -> ''Natural feature''"}, {"source": "remediation_change_log:86822", "url": "remediation_change_log", "quote": "phase4:p4-2153:chunk-0001: description ''Pisissarfik is a 1,220-metre mountain in the Sermersooq municipality, West Greenland, near the settlement of Kapisillit on a branch of the Nuup Kangerlua fjord, about 150 km northeast of Nuuk. The area is archaeologically significant for Norse farmsteads of the Western Settlement (Vestribygd) that operated along the Kapisillit Fjord until around 1350 AD. Conflicts with local Inuit and climate deterioration are believed to have caused the Norse abandonment of the region. Archaeological sites from both Norse and Thule cultures exist within a 2 km radius of Kapisillit.'' -> ''Pisissarfik (old spelling Pisigsarfik) is a 1,220-metre-high mountain in the Sermersooq municipality, West Greenland [1]. The mountain is near the settlement of Kapisillit on the North bank of the Kapisillit Kangerluaq, a branch of the Nuup Kangerlua, about 150 km northeast of the Greenlandic capital Nuuk [1]. The inland side of the mountain is relatively smooth, but it forms a steep cliff by the coast [1]. According to Inuit mythology, the final and decisive battle between the Nordic settlers and themselves took place at the foot of the mountain, and resulted in the extinction of the settlers [1]. The people long considered numerous graves found at the bottom of the cliff to be those of people killed in this fight [1]. However, scientists from the Danish National Museum, who examined the site between 1945 and 1952, found that they were in fact Inuit graves dating from the 16th to 17th century [1]. The graves contained human corpses that had been preserved by natural mummification [1].''"}, {"source": "remediation_change_log:106040", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_name ''1000 - 1500 AD'' -> None"}, {"source": "remediation_change_log:106041", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s016: period_start ''1000'' -> None"}, {"source": "remediation_change_log:159186", "url": "remediation_change_log", "quote": "served-image-2026-09-30-024: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Pisissarfik.jpg/400px-Pisissarfik.jpg'' -> ''/data/images/wiki/b0fdd6ca/hero.webp''"}, {"source": "remediation_change_log:241731", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_name None -> ''1500+ AD''"}, {"source": "remediation_change_log:241732", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s008: period_start None -> ''1501''"}]'::jsonb),
