mediation_change_log:107880", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''3000 - 1500 BC'' -> None"}, {"source": "remediation_change_log:107881", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_start ''-2000'' -> None"}, {"source": "remediation_change_log:160798", "url": "remediation_change_log", "quote": "served-image-2026-09-30-026: thumbnail_url ''/data/images/wiki/c0319301/hero.webp'' -> ''/data/images/wiki/c0319301/Grasburg bei Rottleberode - Chor (1).webp''"}, {"source": "remediation_change_log:242723", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_name None -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:242724", "url": "remediation_change_log", "quote": "2026-10-02b_fields-wd3-s009: period_start None -> ''901''"}, {"source": "remediation_change_log:316641", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-012: thumbnail_url ''/data/images/wiki/c0319301/Grasburg bei Rottleberode - Chor (1).webp'' -> ''/data/images/wiki/c0319301/Grasburg_bei_Rottleberode_-_Chor_(3).webp''"}]'::jsonb),
    ('c70fe2a7-a7d0-4b6e-b59d-b4d1510573bf'::uuid, 'mystery', '10', '9', 'card-stats-2026-11-12-rollback:c70fe2a7-a7d0-4b6e-b59d-b4d1510573bf:mystery', 'rollback of card-stats-2026-11-12: mystery ''9'' restored on Pusuquy Pata', '99656d2bf0aac91b8b6f127ce10a0e96', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 10 from (''Cemetery'', ''500 - 1000 AD'') is shared by 1 curated site(s)"}, {"source": "production export 3433e767f34031a8 (2026-11-12 10:36:17.26111+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 103 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07d''s own export (2026-11-07 15:22:34.233295+00))"}, {"source": "remediation_change_log:81290", "url": "remediation_change_log", "quote": "phase4:p4-2027:chunk-0001: description \"Pusuquy Pata (also known as Posoqoypata) is a Wari culture cemetery in the Huanta District of Peru''s Ayacucho Region, dating to the Middle Horizon period (c. AD 600-1000). Accidentally exposed by a bulldozer in 2000, rescue excavations revealed twelve cylindrical stone-and-clay burial cists and a rectangular mortuary chamber (2.2m x 1.2m) with an east-facing entrance containing remains of multiple individuals. These tomb forms were previously unknown for the Wari culture, and the chamber''s accessible design suggests ancestor veneration practices.\" -> \"Pusuquy Pata (Ayacucho Quechua pusuquy a cactus, pata step, bank of a river, hispanicized spelling Posoqoypata) or Ch''illiku Pampa is an archaeological site in the Ayacucho Region in Peru [1]. It is located in the Huanta Province, Huanta District [1]. The site consists of tombs of the Wari culture [1].\""}, {"source": "remediation_change_log:108037", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s018: period_name ''1 - 500 AD'' -> None"}, {"source": "remediation_change_log:108038", "ur