    ('ca1f8a94-27e1-4318-b3d5-3db181795ffd'::uuid, 'antiquity', '2', '1', 'card-stats-2026-11-12-rollback:ca1f8a94-27e1-4318-b3d5-3db181795ffd:antiquity', 'rollback of card-stats-2026-11-12: antiquity ''1'' restored on Panamá Viejo', '84fc2f23ae7c81f79491ecf151b6dcd5', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 2 from period_start 500"}, {"source": "production export 3433e767f34031a8 (2026-11-12 10:36:17.26111+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 103 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07d''s own export (2026-11-07 15:22:34.233295+00))"}, {"source": "remediation_change_log:27832", "url": "remediation_change_log", "quote": "phase3:batch-0015:chunk-0001: period_start ''1000'' -> ''1519''"}, {"source": "remediation_change_log:30503", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''1000 - 1500 AD'' -> ''1500+ AD''"}, {"source": "remediation_change_log:36013", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_name ''1500+ AD'' -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:36014", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''1519'' -> ''1000''"}, {"source": "remediation_change_log:87430", "url": "remediation_change_log", "quote": "phase4:p4-2171:chunk-0001: description ''Panama Viejo is the oldest continuously occupied European settlement on the Pacific coast of the Americas, founded on August 15, 1519 by Pedro Arias Davila. The ruins cover 32 hectares preserving early colonial urban planning with a rudimentary grid pattern. Archaeological excavations have uncovered evidence of pre-Columbian Cuevan peoples, demonstrating over 700 years of pre-Hispanic occupation before European contact. The city was sacked and burned in 1671 by English pirate Henry Morgan, after which residents relocated 7.5 km southeast to found Casco Antiguo. UNESCO World Heritage Site since 1997, extended in 2003.'' -> ''Panamá Viejo, also known as Panamá la Vieja, is the remaining part of the original Panama City, the former capital of Panama, which was destroyed in 1671 by the Welsh privateer Henry Morgan [1]. It is located in the suburbs of the current capital [1]. A settlement was founded on August 15, 1519 by Pedro Arias Dávila and another 100 inhabitants [1]. At the time, it was the first permanent European settlement on the Pacific Ocean, replacing the two cities of Santa María la Antigua del Darién and Acla [1]. Two years later, in 1521, the settlement was promoted to the status of city by a royal decree and was given a coat of arms by Charles V of Spain, forming a new cabildo [1]. Shortly after its creation, the city became a starting point for various expeditions in Peru and an important base where gold and silver were sent to Spain [1].''"}, {"source": "remediation_change_log:108744", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_name ''1000 - 1500 AD'' -> None"}, {"source": "remediation_change_log:108745", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s019: period_start ''1000'' -> None"}, {"source": "remediation_change_log:141503", "url": "remediation_change_log", "quote": "2026-10-01a_fields-wd3-s001: period_name None -> ''1500+ AD''"}, {"source": "remediation_change_log:141504", "url": "remediation_change_log", "quote": "2026-10-01a_fields-wd3-s001: period_start None -> ''1519''"}, {"source": "remediation_change_log:162120", "url": "remediation_change_log", "quote": "served-image-2026-09-30-028: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/d/d0/Casa_de_los_Genoveses_en_Panam%C3%A1_Viejo.jpg'' -> ''/data/images/wiki/ca1f8a94/Diorama_of_Panamá_Viejo.webp''"}, {"source": "remediation_change_log:317463", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-013: thumbnail_url ''/data/images/wiki/ca1f8a94/Diorama_of_Panamá_Viejo.webp'' -> ''/data/images/wiki/ca1f8a94/Casa_de_los_Genoveses_en_Panamá_Viejo.webp''"}, {"source": "remediation_change_log:418493", "url": "remediation_change_log", "quote": "2026-11-12_mechanical-period-fix-s001: period_name ''1500+ AD'' -> ''500 - 1000 AD''"}, {"source": "remediation_change_log:418494", "url": "remediation_change_log", "quote": "2026-11-12_mechanical-period-fix-s001: period_start ''1519'' -> ''500''"}]'::jsonb),
