    ('d8256f75-7b93-49b5-8910-801bd1591397'::uuid, 'mystery', '9', '10', 'card-stats-2026-11-12-rollback:d8256f75-7b93-49b5-8910-801bd1591397:mystery', 'rollback of card-stats-2026-11-12: mystery ''10'' restored on Einang Stone', '7aed73c7dddc86eee30b110a09073d9f', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "mystery = 9 from (''Inscription'', ''1 - 500 AD'') is shared by 2 curated site(s)"}, {"source": "production export 3433e767f34031a8 (2026-11-12 10:36:17.26111+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 103 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07d''s own export (2026-11-07 15:22:34.233295+00))"}, {"source": "remediation_change_log:28136", "url": "remediation_change_log", "quote": "phase3:batch-0079:chunk-0001: site_type ''Rock relief/carving'' -> ''Inscription''"}, {"source": "remediation_change_log:87778", "url": "remediation_change_log", "quote": "phase4:p4-2182:chunk-0001: description \"The Einang stone is a 4th-century runestone near Fagernes in Oppland, Norway, bearing an Elder Futhark inscription in Proto-Norse that reads ''ek godagastiz runo faihido'' (''I, Godguest, painted/wrote the runes''). It is the oldest runestone still standing at its original location and may contain the earliest known use of the word ''runo'' (rune). The stone sits on a grave mound within the extensive Gardberg burial site on a ridge overlooking the Valdres valley. The verb ''faihido'' literally means ''painted,'' suggesting the original inscription was highlighted with pigment. Today the runestone is protected by glass walls and a roof.\" -> \"The Einang stone is a runestone located to the northeast of the Einangsundet strait near the village of Slidre in Vestre Slidre Municipality in Innlandet county [1]. The stone is notable for the age of its runic inscription [1]. The Einang runestone is located within the extensive Gardberg site [1]. It is placed on a grave mound on a ridge overlooking the Valdres valley [1]. The Einang stone bears an Elder Futhark inscription, written from right to left, in Proto-Norse that has been dated to the 4th century [1]. It is the oldest runestone still standing at its original location, and it may be the earliest inscription to mention the word runo ''rune'' [1]. The generally accepted reading of the inscription was proposed by Erik Moltke in 1938 [1].\""}, {"source": "remediation_change_log:163711", "url": "remediation_change_log", "quote": "served-image-2026-09-30-030: thumbnail_url ''/data/images/wiki/d8256f75/hero.webp'' -> ''/data/images/wiki/d8256f75/Einang finds.webp''"}, {"source": "remediation_change_log:318340", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-014: thumbnail_url ''/data/images/wiki/d8256f75/Einang finds.webp'' -> ''/data/images/wiki/d8256f75/Einangsteinen,_Vestre_Slidre.webp''"}]'::jsonb),
