    ('f5e7956b-9aa4-47b0-b88a-3ed159f451d1'::uuid, 'antiquity', '5', '1', 'card-stats-2026-11-12-rollback:f5e7956b-9aa4-47b0-b88a-3ed159f451d1:antiquity', 'rollback of card-stats-2026-11-12: antiquity ''1'' restored on Llansteffan Castle', '5563e0f1c562a3d953eef7d6490b61c4', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 5 from period_start -600"}, {"source": "production export 3433e767f34031a8 (2026-11-12 10:36:17.26111+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 103 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07d''s own export (2026-11-07 15:22:34.233295+00))"}, {"source": "remediation_change_log:43697", "url": "remediation_change_log", "quote": "phase4:p4-0080:chunk-0001: description ''A castle in Carmarthenshire, Wales, built upon an Iron Age promontory fort first fortified around 600 BC with a double bank and ditch across the headland. The Normans constructed the stone castle after 1100 to control the strategically vital River Tywi estuary crossing. The late 12th-century rough stone walls were augmented by a massive twin-towered gatehouse built around 1280. The original Iron Age earthworks remain visible and were incorporated into the medieval defenses, demonstrating continuous military use of this commanding hilltop position over two millennia.'' -> \"Llansteffan Castle (Welsh: Castell Llansteffan) is a privately owned castle in Llansteffan, Carmarthenshire, Wales, overlooking the River Towy estuary in Carmarthen Bay [1]. The castle sits on a much older Iron Age promontory fort, proving Llansteffan has been inhabited for several millennia [1]. The hill where the castle stands commands the River Towy estuary [1]. The original earthworks can still be seen and were used as part of the modern castle''s defence system—the castle proper rests within the earthwork rings [1].\""}, {"source": "remediation_change_log:126635", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_name ''3000 - 1500 BC'' -> ''1000 - 1500 AD''"}, {"source": "remediation_change_log:126636", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_start ''-3000'' -> ''1101''"}, {"source": "remediation_change_log:166600", "url": "remediation_change_log", "quote": "served-image-2026-09-30-034: thumbnail_url ''/data/images/wiki/f5e7956b/hero.webp'' -> ''/data/images/wiki/f5e7956b/Llansteffan Castle Llansteffan.webp''"}, {"source": "remediation_change_log:319476", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-015: thumbnail_url ''/data/images/wiki/f5e7956b/Llansteffan Castle Llansteffan.webp'' -> ''/data/images/wiki/f5e7956b/Llansteffan_Castle.webp''"}, {"source": "remediation_change_log:418512", "url": "remediation_change_log", "quote": "2026-11-12_mechanical-period-fix-s001: period_name ''1000 - 1500 AD'' -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:418513", "url": "remediation_change_log", "quote": "2026-11-12_mechanical-period-fix-s001: period_start ''1101'' -> ''-600''"}]'::jsonb),
