    ('fa2075b9-ae78-4ce0-b00f-673d0139f0ff'::uuid, 'antiquity', '8', '1', 'card-stats-2026-11-12-rollback:fa2075b9-ae78-4ce0-b00f-673d0139f0ff:antiquity', 'rollback of card-stats-2026-11-12: antiquity ''1'' restored on Saguaro National Park', 'a7cac4ad1e1ef4decdd54aaf291bcff8', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 8 from period_start -3500"}, {"source": "production export 3433e767f34031a8 (2026-11-12 10:36:17.26111+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 103 journalled input value(s) put back reproduce the stored card_stats in all 59556 cells (basis: wave 2026-11-07d''s own export (2026-11-07 15:22:34.233295+00))"}, {"source": "remediation_change_log:88562", "url": "remediation_change_log", "quote": "phase4:p4-2204:chunk-0001: description ''Saguaro National Park in southeastern Arizona preserves extensive rock art created by the Hohokam people, who inhabited the region from approximately 300 to 1450 AD. The Signal Hill site in the Tucson Mountain District contains over 200 petroglyphs featuring geometric spirals, human forms, mountain sheep, deer, and reptiles. Artists used pecking, incising, and abrading techniques on patinated rock surfaces. Designs fall into five classifications: geometric elements, geometric designs, botanical, zoomorphic, and anthropomorphic.'' -> ''Saguaro National Park is a national park of the United States in southeastern Arizona [1]. The 92,000-acre park consists of two separate areas—the Tucson Mountain District, about 10 miles west of Tucson, and the Rincon Mountain District, about 10 miles east of the city [1]. The earliest known residents of the land in and around what later became Saguaro National Park were the Hohokam, who lived there in villages between AD 200 and 1450 [1]. Petroglyphs and bits of broken pottery are among Hohokam artifacts found in the park [1]. Hohokam petroglyphs etched into large stones are easily accessible in the Tucson Mountain District [1]. The Signal Hill Trail leads to an area with dozens of examples of the 800-year-old rock art [1].''"}, {"source": "remediation_change_log:126684", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_name ''1 - 500 AD'' -> ''1500+ AD''"}, {"source": "remediation_change_log:126685", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: period_start ''1'' -> ''1933''"}, {"source": "remediation_change_log:126686", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s011: site_type ''Petroglyphs'' -> ''Natural feature''"}, {"source": "remediation_change_log:166769", "url": "remediation_change_log", "quote": "served-image-2026-09-30-034: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Saguaronationalparl17102008.jpg/400px-Saguaronationalparl17102008.jpg'' -> ''/data/images/wiki/fa2075b9/Saguaronationalparl17102008.webp''"}, {"source": "remediation_change_log:418514", "url": "remediation_change_log", "quote": "2026-11-12_mechanical-period-fix-s001: period_name ''1500+ AD'' -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:418515", "url": "remediation_change_log", "quote": "2026-11-12_mechanical-period-fix-s001: period_start ''1933'' -> ''-3500''"}]'::jsonb),
